  'A protein-rich meal before bed (cottage cheese, yoghurt) is even useful; just not so big it ruins sleep.':
    'Baltymingas valgis prieš miegą (varškė, jogurtas) netgi naudingas – tik ne toks didelis, kad sugadintų miegą.',
