  'A regular bedtime, within about {1} minutes each night, matters nearly as much as total hours.':
    'Reguliarus ėjimo miegoti laikas (kasnakt maždaug {1} min. tikslumu) svarbus beveik tiek pat, kiek bendras valandų skaičius.',
