  'How far the knees travel depends on your limb lengths and ankle mobility — long thighs usually mean more forward knee travel.':
    'Kiek keliai juda į priekį, priklauso nuo galūnių ilgio ir čiurnos paslankumo – ilgos šlaunys paprastai reiškia daugiau kelių judėjimo į priekį.',
  'How is my bench progressing?': 'Kaip progresuoja mano spaudimas gulint?',
  'How is my injury?': 'Kaip mano trauma?',
  'How is my {1} going?': 'Kaip sekasi su {1}?',
  'How long do I actually rest?': 'Kiek aš iš tikrųjų ilsiuosi?',
  'How long should I rest between sets?': 'Kiek ilsėtis tarp priėjimų?',
  'How long should I rest?': 'Kiek ilsėtis?',
  'How long should a workout be?': 'Kiek turi trukti treniruotė?',
  'How many calories do I need?': 'Kiek kalorijų man reikia?',
  'How many carbs?': 'Kiek angliavandenių?',
