  'How often should I train chest?': 'Kaip dažnai treniruoti krūtinę?',
  'How often should I train {1}?': 'Kaip dažnai treniruoti: {1}?',
  'How should I adjust training as I get older?': 'Kaip keisti treniruotes senstant?',
